using ProjetoIntegradorBack.Domain.Entities; using ProjetoIntegradorBack.Domain.Enums; using ProjetoIntegradorBack.Domain.Interfaces; using ProjetoIntegradorBack.Infrastructure.Context; using ProjetoIntegradorBack.Shared.Pattern; using Microsoft.EntityFrameworkCore;
namespace ProjetoIntegradorBack.Infrastructure.Repositories;
public class AppointmentRepository(ProjetoIntegradorBackDbContext context):IAppointmentRepository{
public async Task<Result<Appointment>> GetPorIdAsync(Guid id,CancellationToken ct=default){try{var e=await context.Appointments.Include(x=>x.Cliente).Include(x=>x.Establishment).Include(x=>x.Employee).Include(x=>x.Service).FirstOrDefaultAsync(x=>x.Id==id,ct);return e==null?Result<Appointment>.AsFailure(new Failure(404,"Appointment não encontrado.")):Result<Appointment>.AsSuccess(e);}catch(Exception ex){return Result<Appointment>.AsFailure(new Failure(500,ex.Message));}}
public async Task<Result<IReadOnlyList<Appointment>>> GetPorClienteAsync(Guid id,StatusAppointment? status,int page,int size,CancellationToken ct=default){try{var q=context.Appointments.Where(x=>x.ClientId==id);if(status.HasValue)q=q.Where(x=>x.Status==status);return Result<IReadOnlyList<Appointment>>.AsSuccess(await q.OrderByDescending(x=>x.DateTime).Skip((page-1)*size).Take(size).ToListAsync(ct));}catch(Exception ex){return Result<IReadOnlyList<Appointment>>.AsFailure(new Failure(500,ex.Message));}}
public async Task<Result<int>> ContarPorClienteAsync(Guid id,StatusAppointment? status,CancellationToken ct=default){try{var q=context.Appointments.Where(x=>x.ClientId==id);if(status.HasValue)q=q.Where(x=>x.Status==status);return Result<int>.AsSuccess(await q.CountAsync(ct));}catch(Exception ex){return Result<int>.AsFailure(new Failure(500,ex.Message));}}
public Task<Result<IReadOnlyList<Appointment>>> GetPorEmployeeNoMonthAsync(Guid id,int year,int month,CancellationToken ct=default)=>Periodo(id,x=>x.DateTime.Year==year&&x.DateTime.Month==month,ct);
public async Task<Result<IReadOnlyList<Appointment>>> GetPorEmployeeNoDateAsync(Guid id,DateOnly day,CancellationToken ct=default){var ini=day.ToDateTime(TimeOnly.MinValue);var end=day.ToDateTime(TimeOnly.MaxValue);return await Periodo(id,x=>x.DateTime>=ini&&x.DateTime<=end,ct);}
private async Task<Result<IReadOnlyList<Appointment>>> Periodo(Guid id,System.Linq.Expressions.Expression<Func<Appointment,bool>> p,CancellationToken ct){try{return Result<IReadOnlyList<Appointment>>.AsSuccess(await context.Appointments.Where(x=>x.EmployeeId==id).Where(p).OrderBy(x=>x.DateTime).ToListAsync(ct));}catch(Exception ex){return Result<IReadOnlyList<Appointment>>.AsFailure(new Failure(500,ex.Message));}}
public async Task<Result<Appointment>> AddAsync(Appointment e,CancellationToken ct=default){try{e.Id=Guid.NewGuid();e.CreatedAt=DateTime.UtcNow;e.BookingNumber=$"BT-{DateTime.UtcNow:yyyyMMdd}-{Guid.NewGuid().ToString()[..6].ToUpper()}";await context.Appointments.AddAsync(e,ct);await context.SaveChangesAsync(ct);return Result<Appointment>.AsSuccess(e);}catch(Exception ex){return Result<Appointment>.AsFailure(new Failure(500,ex.Message));}}
public async Task<Result<Appointment>> UpdateAsync(Appointment e,CancellationToken ct=default){try{e.UpdatedAt=DateTime.UtcNow;context.Appointments.Update(e);await context.SaveChangesAsync(ct);return Result<Appointment>.AsSuccess(e);}catch(Exception ex){return Result<Appointment>.AsFailure(new Failure(500,ex.Message));}}
public async Task<Result<bool>> HasTimeConflictAsync(Guid id,DateTime dateHora,int duracaoMin,CancellationToken ct=default){try{var end=dateHora.AddMinutes(duracaoMin);return Result<bool>.AsSuccess(await context.Appointments.Include(x=>x.Service).Where(x=>x.EmployeeId==id&&x.Status!=StatusAppointment.Cancelado).AnyAsync(x=>dateHora<x.DateTime.AddMinutes(x.Service.DurationMinutes)&&end>x.DateTime,ct));}catch(Exception ex){return Result<bool>.AsFailure(new Failure(500,ex.Message));}}
public async Task<Result<IReadOnlyList<Appointment>>> GetPorEstablishmentNoPeriodoAsync(Guid id,DateTime start,DateTime end,CancellationToken ct=default){try{return Result<IReadOnlyList<Appointment>>.AsSuccess(await context.Appointments.Where(x=>x.EstablishmentId==id&&x.DateTime>=start&&x.DateTime<=end).ToListAsync(ct));}catch(Exception ex){return Result<IReadOnlyList<Appointment>>.AsFailure(new Failure(500,ex.Message));}}}